{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C37"],
      "claim": "Indomethacin sustained-release has absolute bioavailability of 76% in humans, showing that a lipophilic, poorly soluble indole/chlorophenyl drug can achieve high oral F; high transfer supports high for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Rigosertib, a high-molecular-weight polyaromatic/methoxy-containing drug, has absolute oral bioavailability of 35% in fasting patients, directly supporting F >= 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Loratadine, a lipophilic chlorophenyl tricyclic drug, shows good oral bioavailability in healthy volunteers, supporting high F for a similarly lipophilic heteroaromatic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "GDC-0810, a structurally complex chlorophenyl/indazole drug, is predicted to have approximately 45% oral bioavailability by PBPK, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Alfuzosin, a dimethoxyquinazoline with an aminopyrimidine-like core, has 49% absolute bioavailability under fed conditions, directly supporting high F for the query's methoxy/heteroaromatic features.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer experimental analogues consistently show absolute oral bioavailability of 35-100%, including complex lipophilic and heteroaromatic drugs. This transferable evidence overrides the uncertain physicochemical prior of low F, supporting a high bioavailability prediction (F >= 20%).",
  "evidence_gaps": [
    "No direct human absolute bioavailability data exist for the exact query molecule.",
    "Some high-transfer records are predicted or use unspecified bioavailability reporting, adding minor uncertainty.",
    "Low-transfer records for thiamine, melatonin, and mebendazole were excluded due to negligible transferability.",
    "The physicochemical prior suggests solubility risk, but no direct solubility/dissolution data for the query are available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

